package cn.bidcheck.verification.engine;

import java.util.*;
import java.util.function.Supplier;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static org.junit.jupiter.api.Assertions.*;

class ConfirmedSubjectBindingsTest {
    final PersonnelCountRoleTest helper=new PersonnelCountRoleTest();
    EvidenceCorpus corpus(){return helper.corpus("本项目人员配置\n项目负责人：李明","本项目人员资格证明\n一级注册建造师注册证书\n姓名：李*\n注册编号：京1112025202600101\n聘用单位：合成建筑有限公司\n注册专业：建筑工程\n注册有效期：2024-01-01至2028-01-01");}
    Fact role(EvidenceCorpus c){return helper.role(c,1,"项目负责人","李明","","");}
    Fact certificate(EvidenceCorpus c){return new Fact("masked-cert","CERTIFICATE","李*","证书","京1112025202600101","一级注册建造师","","","UNRESOLVED",cn.bidcheck.compat.Java8Api.listOf(helper.source(c,2).id()),cn.bidcheck.compat.Java8Api.mapOf("category", "一级注册建造师", "number", "京1112025202600101", "numberField", "注册编号", "profession", "建筑工程"));}
    Rule rule(boolean typed){Map<String,Object> p=new LinkedHashMap<>(cn.bidcheck.compat.Java8Api.mapOf("category", "一级注册建造师", "profession", "建筑工程"));if(typed)p.putAll(cn.bidcheck.compat.Java8Api.mapOf("personnelCredentialKind", "REGISTERED_BUILDER", "requiredGrade", "一级", "requiredProfession", "建筑工程", "gradeInclusive", false));return new Rule("cert","人员证照","CERTIFICATE","项目负责人","证书","","","",p,"项目负责人应提供一级注册建造师执业资格证书（建筑工程专业）","",cn.bidcheck.compat.Java8Api.listOf());}
    Fact confirmation(EvidenceCorpus c,List<Source> citations){java.util.List<java.util.Map<java.lang.String, java.lang.Object>> evidences=cn.bidcheck.compat.Java8Api.toList(citations.stream().map(s->linked("sourceId",s.id(),"quote",s.evidence().quote(),"documentHash",s.documentHash(),"documentVersion",s.documentVersion())));Map<String,Object> candidate=linked("kind","RELATION","subject","李明","field","同一人","rawValue","李*","value","李*","scope","CURRENT_PROJECT","attributes",cn.bidcheck.compat.Java8Api.mapOf("object", "李*"));java.util.Map<java.lang.String, java.lang.Object> row=linked("id","confirmed-pair","status","CONFIRMED","actor","test-reviewer","decidedAt","2026-11-02T00:00:00Z","targetId","cert","targetFingerprint","test-target","evidences",evidences,"proposedFact",candidate);return InferenceClaims.confirmed(cn.bidcheck.compat.Java8Api.mapOf("confirmedInferenceLookup", (Supplier<Object>)()->cn.bidcheck.compat.Java8Api.listOf(row)),c).get(0);}
    @Test void humanConfirmationClosesOnlyIdentityAndRetainsTheOriginalHolderAndFields(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();Fact role=role(c),cert=certificate(c);assertNull(new ProofVerifier().issue(cert,c.byId));cn.bidcheck.verification.engine.VerificationTypes.Decision initial=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(role, cert),c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(rule(false));assertEquals("UNDETERMINED",initial.status());Fact approved=confirmation(c,c.all);cn.bidcheck.verification.engine.RuleEvaluator evaluator=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(role, cert, approved),c,cn.bidcheck.compat.Java8Api.mapOf());assertEquals("PASS",evaluator.evaluate(rule(false)).status());assertEquals("李*",evaluator.match(rule(false)).get(0).subject());assertTrue(evaluator.identities.samePerson(role,cert));assertTrue(evaluator.identities.bindings(cn.bidcheck.compat.Java8Api.listOf(cert)).toString().contains("HUMAN_CONFIRMED_CITED_IDENTITY_PAIR"));}
    @Test void typedCredentialExecutorStillReadsUnmodifiedSourceAfterIdentityConfirmation(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();cn.bidcheck.verification.engine.RuleEvaluator evaluator=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(role(c), certificate(c), confirmation(c,c.all)),c,cn.bidcheck.compat.Java8Api.mapOf());cn.bidcheck.verification.engine.VerificationTypes.Decision d=evaluator.evaluate(rule(true));assertEquals("PASS",d.status(),d.toString());assertTrue(d.proof().toString().contains("李*"));}
    @Test void confirmationCannotBeForgedOrReusedForAnotherUncitedSource(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();Fact role=role(c),cert=certificate(c),approved=confirmation(c,c.all);Map<String,Object> forged=new LinkedHashMap<>(approved.attributes());forged.put("humanConfirmation",cn.bidcheck.compat.Java8Api.mapOf("claimId", "confirmed-pair"));Fact fake=new Fact("forged",approved.kind(),approved.subject(),approved.field(),approved.rawValue(),approved.value(),"","",approved.scope(),approved.sourceIds(),forged);assertFalse(new SubjectIdentity(cn.bidcheck.compat.Java8Api.listOf(role, cert, fake),c,cn.bidcheck.compat.Java8Api.listOf()).samePerson(role,cert));Fact onlyProof=confirmation(c,cn.bidcheck.compat.Java8Api.listOf(helper.source(c,2)));assertFalse(new SubjectIdentity(cn.bidcheck.compat.Java8Api.listOf(role, cert, onlyProof),c,cn.bidcheck.compat.Java8Api.listOf()).samePerson(role,cert));}
    @Test void confirmingIdentityCannotFabricateMissingCredentialFields(){cn.bidcheck.verification.engine.EvidenceCorpus c=corpus();Fact original=certificate(c);Fact incomplete=new Fact(original.id(),original.kind(),original.subject(),original.field(),original.rawValue(),original.value(),"","",original.scope(),original.sourceIds(),cn.bidcheck.compat.Java8Api.mapOf("category", "一级注册建造师", "number", "京1112025202600101", "numberField", "注册编号"));assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(role(c), incomplete, confirmation(c,c.all)),c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(rule(false)).status());}
    @Test void explicitContradictoryIdentityInTheCredentialCannotBeOverriddenByConfirmation(){cn.bidcheck.domain.Domain.Document original=corpus().documents.get(0);java.util.List<cn.bidcheck.domain.Domain.Page> pages=cn.bidcheck.compat.Java8Api.toList(original.pages().stream().map(p->new cn.bidcheck.domain.Domain.Page(p.number(),p.number()==1?p.text()+"\n姓名：李明\n身份证号：110101199001010011":p.text().replace("姓名：李*","姓名：李*\n性别：男\n"+cn.bidcheck.compat.Java8Api.repeat("附注", 100)+"\n身份证号：110101198001010010"),p.locationType(),p.parser(),p.warning())));cn.bidcheck.verification.engine.EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new cn.bidcheck.domain.Domain.Document(original.id(),original.projectId(),original.role(),original.name(),original.version(),original.sha256(),original.createdAt(),pages,original.warnings())));Fact cert=certificate(c);java.util.List<cn.bidcheck.verification.engine.CertificateSourceComparison.Record> records=CertificateRecordBindings.records(c,cn.bidcheck.compat.Java8Api.toList(c.all.stream().filter(s->s.evidence().page()==2)));assertFalse(records.isEmpty());assertEquals("110101198001010010",records.get(0).value("PERSON_ID"));Fact approved=confirmation(c,c.all);assertFalse(new SubjectIdentity(cn.bidcheck.compat.Java8Api.listOf(role(c), cert, approved),c,cn.bidcheck.compat.Java8Api.listOf()).samePerson(role(c),cert));assertNotEquals("PASS",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(role(c), cert, approved),c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(rule(false)).status());}
}
